"""Data models for transactions and blocks."""
from __future__ import annotations

import json
from dataclasses import dataclass

from . import crypto

# Block lifecycle states for the confirm/rollback state machine.
STATUS_PENDING = "pending"
STATUS_CONFIRMED = "confirmed"
BLOCK_STATUSES = (STATUS_PENDING, STATUS_CONFIRMED)


@dataclass
class Transaction:
    sender: str
    recipient: str
    amount: int
    signature: str
    # None marks a legacy transfer signed over crypto.canonical_message; a
    # non-boolean non-negative integer marks a sequenced transfer signed over
    # crypto.sequenced_message and bound to the sender's per-account sequence.
    nonce: int | None = None

    @property
    def message(self) -> bytes:
        if self.nonce is None:
            return crypto.canonical_message(self.sender, self.recipient, self.amount)
        return crypto.sequenced_message(
            self.sender, self.recipient, self.amount, self.nonce
        )

    @property
    def tx_id(self) -> str:
        return crypto.compute_tx_id(self.message)

    @property
    def sequenced(self) -> bool:
        return self.nonce is not None

    def to_dict(self) -> dict:
        """JSON-safe representation used both for storage and API output."""
        result = {
            "from": self.sender,
            "to": self.recipient,
            "amount": self.amount,
            "signature": self.signature,
        }
        # The nonce is present only on sequenced transfers, so a legacy
        # transaction keeps its exact five-field wire shape.
        if self.nonce is not None:
            result["nonce"] = self.nonce
        result["tx_id"] = self.tx_id
        return result

    @classmethod
    def from_dict(cls, data: dict) -> "Transaction":
        # The raw JSON value is validated BEFORE any use: no int()/str()
        # coercion, so a string, float or boolean amount can never masquerade
        # as the integer it converts to. bool is an int subclass and must be
        # rejected explicitly.
        amount = data["amount"]
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError("transaction amount must be an integer")
        # A present nonce must already be a non-boolean, non-negative integer
        # — never a coercible string, float, bool or negative. A missing key
        # denotes a legacy transfer and stays None.
        nonce = data.get("nonce")
        if nonce is not None and (
            isinstance(nonce, bool) or not isinstance(nonce, int) or nonce < 0
        ):
            raise ValueError("transaction nonce must be a non-negative integer")
        return cls(
            sender=data["from"],
            recipient=data["to"],
            amount=amount,
            signature=data["signature"],
            nonce=nonce,
        )


def block_header_bytes(height: int, prev_hash: str, merkle: str) -> bytes:
    """Deterministic serialization of the fields covered by the block hash.

    No timestamp is included: a block with the same parent and the same ordered
    transactions must always hash identically.
    """
    header = {"height": height, "merkle_root": merkle, "prev_hash": prev_hash}
    return json.dumps(header, sort_keys=True, separators=(",", ":")).encode("utf-8")


def compute_block_hash(height: int, prev_hash: str, merkle: str) -> str:
    return crypto.sha256_hex(block_header_bytes(height, prev_hash, merkle))


@dataclass
class Block:
    height: int
    prev_hash: str
    merkle_root: str
    transactions: list[Transaction]
    block_hash: str
    status: str = STATUS_CONFIRMED

    @classmethod
    def create(
        cls,
        height: int,
        prev_hash: str,
        transactions: list[Transaction],
        status: str = STATUS_CONFIRMED,
    ) -> "Block":
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        ordered = sorted(transactions, key=lambda tx: tx.tx_id)
        merkle = crypto.merkle_root([tx.tx_id for tx in ordered])
        block_hash = compute_block_hash(height, prev_hash, merkle)
        return cls(
            height=height,
            prev_hash=prev_hash,
            merkle_root=merkle,
            transactions=ordered,
            block_hash=block_hash,
            status=status,
        )

    def to_dict(self) -> dict:
        return {
            "height": self.height,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "block_hash": self.block_hash,
            "status": self.status,
            "transactions": [tx.to_dict() for tx in self.transactions],
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Block":
        # State files written before the status machine existed have no
        # "status" key; every block in such a file was final, so they load
        # as confirmed. This compatibility default never extends to numeric
        # coercion: the raw height must already be a non-boolean,
        # non-negative integer — a string, float or bool is rejected, never
        # converted.
        status = data.get("status", STATUS_CONFIRMED)
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        height = data["height"]
        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            raise ValueError("block height must be a non-negative integer")
        transactions = data["transactions"]
        if not isinstance(transactions, list):
            raise ValueError("block transactions must be a list")
        return cls(
            height=height,
            prev_hash=data["prev_hash"],
            merkle_root=data["merkle_root"],
            block_hash=data["block_hash"],
            transactions=[Transaction.from_dict(t) for t in transactions],
            status=status,
        )

    def to_summary(self) -> dict:
        """Response shape for GET /v1/blocks/{height}."""
        return {
            "height": self.height,
            "block_hash": self.block_hash,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "status": self.status,
            "transaction_ids": [tx.tx_id for tx in self.transactions],
        }

                STATUS_CONFIRMED
                if block.status == STATUS_CONFIRMED
                else STATUS_PENDING
            )
    if tx_id in self.store.pending:
        return STATUS_PENDING
    return None

def get_account_sequence(self, account: object) -> tuple[int, dict]:
    """GET /v1/accounts/{account}/sequence — the account's nonce stream.

    Returns ``{account, next_sequence, pending_sequences,
    confirmed_sequences}``; the two arrays list ``{nonce, tx_id}`` pairs
    ascending by nonce. An account that has never sent a sequenced
    transfer (a "stranger") still answers 200 with next_sequence 0 and
    empty arrays. A non-string or empty account is 400 input.
    """
    if not isinstance(account, str) or not account:
        return 400, {"error": "input"}
    with self.store.lock:
        state = self.store.sequences.get(account)
        if state is None:
            return 200, {
                "account": account,
                "next_sequence": 0,
                "pending_sequences": [],
                "confirmed_sequences": [],
            }
        confirmed = [
            {"nonce": nonce, "tx_id": state["confirmed"][nonce]}
            for nonce in sorted(state["confirmed"])
        ]
        reserved = [
            {"nonce": nonce, "tx_id": state["pending"][nonce]}
            for nonce in sorted(state["pending"])
        ]
        return 200, {
            "account": account,
            "next_sequence": self.store.sequence_next(state),
            "pending_sequences": reserved,
            "confirmed_sequences": confirmed,
        }

def get_transaction(self, tx_id: object) -> tuple[int, dict]:
    """GET /v1/transactions/{tx_id} — one transaction receipt.

    The lookup covers the canonical chain and the mempool only; candidate
    forks are never exposed. A ``tx_id`` that is not exactly 64 lowercase
    hex characters, or one nothing holds, returns 404.

    A mempool transaction is reported ``pending`` with ``height``,
    ``block_hash`` and ``index`` all null. A transaction packed into the
    unconfirmed tip block is ``pending`` too, anchored at that block with
    its 0-based in-block index. A transaction in a confirmed block is
    ``confirmed``. Every receipt is built from the stored signed
    transaction: the id is recomputed from its canonical message (never
    taken from an index or a fork-side cache) and the fields are strictly
    re-typed (non-empty strings, a positive non-boolean integer amount),
    so adoption, rollback and restart can only ever surface the current
    canonical/pending state.
    """
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction not found"}
    with self.store.lock:
        # Canonical chain first: confirmed blocks, then at most one
        # pending tip. The stored signed transaction is the sole source
        # for the receipt, and its id is recomputed rather than trusted
        # from any lookup key.
        for block in self.store.chain:
            for index, tx in enumerate(block.transactions):
                if tx.tx_id != tx_id:
                    continue
                if not self._is_receipt_tx_well_typed(tx):
                    return 404, {"error": "transaction not found"}
                status = (
                    STATUS_CONFIRMED
                    if block.status == STATUS_CONFIRMED
                    else STATUS_PENDING
                )
                return 200, self._transaction_receipt(
                    tx, status, block.height, block.block_hash, index
                )
        # Still unpacked in the mempool.
        tx = self.store.pending.get(tx_id)
        if tx is not None:
            if not self._is_receipt_tx_well_typed(tx):
                return 404, {"error": "transaction not found"}
            return 200, self._transaction_receipt(
                tx, STATUS_PENDING, None, None, None
            )
        return 404, {"error": "transaction not found"}

@staticmethod
def _is_receipt_tx_well_typed(tx: Transaction) -> bool:
    """Strict receipt-time type check of a stored signed transaction.

    Every stored transaction already passed these checks at submission
    (and again during snapshot recovery); the re-check guarantees a
    receipt can never serialize a value that violates the response
    contract, even if an in-memory invariant were broken.
    """
    return (
        isinstance(tx.sender, str)
        and bool(tx.sender)
        and isinstance(tx.recipient, str)
        and bool(tx.recipient)
        and isinstance(tx.amount, int)
        and not isinstance(tx.amount, bool)
        and tx.amount > 0
        and isinstance(tx.signature, str)
        and bool(tx.signature)
        and (
            tx.nonce is None
            or (isinstance(tx.nonce, int) and not isinstance(tx.nonce, bool) and tx.nonce >= 0)
        )
    )

@staticmethod
def _transaction_receipt(
    tx: Transaction,
    status: str,
    height: int | None,
    block_hash: str | None,
    index: int | None,
) -> dict:
    """The fixed nine-field receipt shape for legacy transfers.

    A sequenced transfer appends one further field, ``nonce`` (its
    non-negative sequence number), after ``index``; a legacy transfer
    keeps the exact nine-field document unchanged.
    """
    receipt = {
        "tx_id": tx.tx_id,
        "from": tx.sender,
        "to": tx.recipient,
        "amount": tx.amount,
        "signature": tx.signature,
        "status": status,
        "height": height,
        "block_hash": block_hash,
        "index": index,
    }
    if tx.nonce is not None:
        receipt["nonce"] = tx.nonce
    return receipt

# At most this many distinct ids are accepted by one batch receipt query.
RECEIPTS_MAX_TX_IDS = 200

def get_transaction_receipts(self, payload: object) -> tuple[int, dict]:
    """POST /v1/transactions/receipts — a batch of ordinary transaction
    receipts against one persisted ledger state.

    The body must be a JSON object containing exactly the ``tx_ids``
    key: an array of between one and ``RECEIPTS_MAX_TX_IDS`` distinct
    strings, each exactly 64 lowercase hex characters. Every other
    shape — a non-object body, a missing or extra key, a non-array or
    out-of-range array, a malformed element, or a duplicate — is 400
    ``{"error": "input"}`` and never reaches the lookup; a well-formed
    but unknown id is not an input error.

    A legal batch is always answered 200 with the fixed key order
    ``items, total``: ``total`` equals the number of requested ids and
    ``items`` keeps the request order exactly. Each item has the fixed
    key order ``tx_id, receipt, error``: a hit carries the exact
    :meth:`get_transaction` receipt (same fields, types and meaning)
    with ``error`` null; a miss carries a null ``receipt`` and
    ``not_found`` — an id held only by a candidate fork, or retired by a
    rollback or fork adoption, is a miss. The whole batch is resolved
    under one store lock, so concurrent commits, confirms, rollbacks or
    fork adoptions can never make one response straddle two ledger
    states; the query is read-only.
    """
    bad_input = 400, {"error": "input"}
    if not isinstance(payload, dict) or set(payload) != {"tx_ids"}:
        return bad_input
    tx_ids = payload["tx_ids"]
    if not isinstance(tx_ids, list) or not (
        1 <= len(tx_ids) <= self.RECEIPTS_MAX_TX_IDS
    ):
        return bad_input
    if any(not crypto.is_hex64(tx_id) for tx_id in tx_ids):
        return bad_input
    if len(set(tx_ids)) != len(tx_ids):
        return bad_input

    with self.store.lock:
        # Resolve every id against one persisted-state snapshot: the
        # canonical chain first (confirmed blocks, then at most one
        # pending tip), then the mempool. Candidate forks are never
        # iterated, and receipts are rebuilt from the stored signed
        # transactions exactly as for the single-receipt endpoint.
        requested = set(tx_ids)
        located: dict[str, tuple[str, int, str, int, Transaction]] = {}
        for block in self.store.chain:
            status = (
                STATUS_CONFIRMED
                if block.status == STATUS_CONFIRMED
                else STATUS_PENDING
            )
            for index, tx in enumerate(block.transactions):
                if tx.tx_id in requested and tx.tx_id not in located:
                    located[tx.tx_id] = (
                        status,
                        block.height,
                        block.block_hash,
                        index,
                        tx,
                    )
        items: list[dict] = []
        for tx_id in tx_ids:
            match = located.get(tx_id)
            if match is None:
                tx = self.store.pending.get(tx_id)
                if tx is None:
                    items.append(
                        {"tx_id": tx_id, "receipt": None, "error": "not_found"}
                    )
                    continue
                match = (STATUS_PENDING, None, None, None, tx)
            status, height, block_hash, index, tx = match
            if not self._is_receipt_tx_well_typed(tx):
                # A stored value violating the receipt contract is
                # treated as absent rather than serialized, exactly as
                # the single-receipt endpoint's 404.
                items.append(
                    {"tx_id": tx_id, "receipt": None, "error": "not_found"}
                )
                continue
            items.append(
                {
                    "tx_id": tx_id,
                    "receipt": self._transaction_receipt(
                        tx, status, height, block_hash, index
                    ),
                    "error": None,
                }
            )
        return 200, {"items": items, "total": len(items)}

def get_finalized_receipt(self, tx_id: object) -> tuple[int, dict]:
    """GET /v1/transactions/{tx_id}/finalized-receipt — an offline-verifiable
    finalized transaction receipt.

    Lookup and typing rules mirror :meth:`get_transaction`: a ``tx_id``
    that is not exactly 64 lowercase hex characters, or one nothing
    holds on the canonical chain (the mempool and candidate forks are
    not matches here), returns 404. A transaction still in the mempool
    or packed into the unconfirmed pending tip is not final and returns
    409.

    On success the whole document is snapshotted under one store lock
    together with the current audit signer, so the receipt, proof,
    headers and finality credential can never mix chain states. The
    body has the fixed key order ``receipt, proof, headers, finality``:
    ``receipt`` is the fixed nine-field receipt with ``status``
    confirmed; ``proof`` is the single-transaction Merkle proof of
    ``GET /v1/blocks/{height}/proof/{tx_id}``; ``headers`` run from the
    transaction's own confirmed block up to and including the highest
    confirmed block in ascending height, each item in the signed header
    page's five-field shape (every item confirmed); and ``finality`` is
    exactly the ``GET /v1/chain/finality`` document, whose
    ``finalized`` names that last header.
    """
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction not found"}
    from . import light_client

    with self.store.lock:
        matched: tuple[Block, int, Transaction] | None = None
        for block in self.store.chain:
            for index, tx in enumerate(block.transactions):
                if tx.tx_id == tx_id:
                    matched = (block, index, tx)
                    break
            if matched is not None:
                break
        if matched is None:
            # Neither the canonical chain nor (below) the mempool holds
            # the id; candidate forks are never exposed.
            if tx_id in self.store.pending:
                return 409, {"error": "transaction is not confirmed"}
            return 404, {"error": "transaction not found"}
        block, index, tx = matched
        if not self._is_receipt_tx_well_typed(tx):
            return 404, {"error": "transaction not found"}
        if block.status != STATUS_CONFIRMED:
            # A packed-but-unconfirmed transaction can only sit in the
            # pending chain tip.
            return 409, {"error": "transaction is not confirmed"}

        tx_ids = [candidate.tx_id for candidate in block.transactions]
        proof = {
            "height": block.height,
            "tx_id": tx.tx_id,
            "index": index,
            "merkle_root": block.merkle_root,
            "block_hash": block.block_hash,
            "siblings": crypto.merkle_proof(tx_ids, index),
        }

        finalized_block = next(
            candidate
            for candidate in reversed(self.store.chain)
            if candidate.status == STATUS_CONFIRMED
        )
        # Every block from the transaction's block through the highest
        # confirmed block is confirmed: the only pending block the chain
        # ever carries is its tip, which the slice stops before.
        headers = [
            self._header_entry(candidate)
            for candidate in self.store.chain[
                block.height : finalized_block.height + 1
            ]
        ]
        finalized = self._anchor_descriptor(finalized_block)
        tip = self._fork_summary(self.store.chain)
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot (including migrated legacy ones) carries a
            # current audit signer after recovery; reaching here is a
            # programming error rather than a client-visible condition.
            raise RuntimeError(
                "no audit signer available for finalized receipt"
            )
        auth = light_client.sign_finality(
            signer["private_key"], signer["version"], finalized, tip
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        finality = {
            "finalized": finalized,
            "tip": tip,
            "auth": auth,
        }
        return 200, {
            "receipt": self._transaction_receipt(
                tx, STATUS_CONFIRMED, block.height, block.block_hash, index
            ),
            "proof": proof,
            "headers": headers,
            "finality": finality,
        }

def get_finalized_receipts(self, payload: object) -> tuple[int, dict]:
    """POST /v1/transactions/finalized-receipts — a batch of
    offline-verifiable finalized receipts sharing one chain snapshot.

    The body must be a JSON object containing exactly the ``tx_ids``
    key: a non-empty list of distinct 64-lowercase-hex strings (the
    same rules as ``POST /v1/blocks/{height}/proofs``). A malformed
    body — parse failure, missing/extra keys, a wrong type, an empty
    list, duplicates or a wrongly formatted id — is 400 and never
    touches state. If every id is well formed but any of them is held
    neither on the canonical chain nor in the mempool (candidate forks
    are never matches), the answer is 404; otherwise, when nothing is
    missing but at least one transaction is still in the mempool or
    packed into the unconfirmed pending tip, the answer is 409.

    On success the chain and the current audit signer are snapshotted
    together under one store lock (exactly as for
    :meth:`get_finalized_receipt`), so every item, the shared header
    run and the finality credential can never mix chain states. The
    body has the fixed key order ``items, headers, finality``:
    ``items`` is ordered by ``tx_id`` ascending regardless of the
    request order, and each item has the fixed key order
    ``receipt, proof`` using the exact single-receipt contract;
    ``headers`` is the continuous five-field confirmed header run from
    the **lowest** transaction's block up to and including the highest
    confirmed block (every item confirmed); ``finality`` is exactly the
    ``GET /v1/chain/finality`` document, whose ``finalized`` names the
    last header.
    """
    if not isinstance(payload, dict) or set(payload) != {"tx_ids"}:
        return 400, {"error": "request body must be a JSON object with only 'tx_ids'"}
    tx_ids_raw = payload["tx_ids"]
    if not isinstance(tx_ids_raw, list) or not tx_ids_raw:
        return 400, {"error": "field 'tx_ids' must be a non-empty array"}
    if any(not crypto.is_hex64(tx_id) for tx_id in tx_ids_raw):
        return 400, {
            "error": "every tx_id must be a string of 64 lowercase hex characters"
        }
    if len(set(tx_ids_raw)) != len(tx_ids_raw):
        return 400, {"error": "tx_ids must be distinct"}

    from . import light_client

    with self.store.lock:
        requested = sorted(tx_ids_raw)
        requested_set = set(requested)
        # One pass over the canonical chain (which includes the pending
        # tip) locates every request id at its first inclusion point.
        located: dict[str, tuple[Block, int, Transaction]] = {}
        for block in self.store.chain:
            for index, tx in enumerate(block.transactions):
                if tx.tx_id in requested_set and tx.tx_id not in located:
                    located[tx.tx_id] = (block, index, tx)
        # A 404 takes precedence over a 409: an id absent from both the
        # chain and the mempool does not exist, even if another id of
        # the same batch is merely unconfirmed.
        unknown = [
            tx_id
            for tx_id in requested
            if tx_id not in located
            and tx_id not in self.store.pending
        ]
        if unknown:
            return 404, {"error": "transaction not found"}
        for tx_id, (_block, _index, tx) in located.items():
            if not self._is_receipt_tx_well_typed(tx):
                return 404, {"error": "transaction not found"}
        if any(
            tx_id in self.store.pending
            or located[tx_id][0].status != STATUS_CONFIRMED
            for tx_id in requested
        ):
            # Packed-but-unconfirmed transactions can only sit in the
            # pending chain tip; everything else here is in the mempool.
            return 409, {"error": "transaction is not confirmed"}

        items = []
        lowest_height: int | None = None
        for tx_id in requested:
            block, index, tx = located[tx_id]
            if lowest_height is None or block.height < lowest_height:
                lowest_height = block.height
            items.append(
                {
                    "receipt": self._transaction_receipt(
                        tx,
                        STATUS_CONFIRMED,
                        block.height,
                        block.block_hash,
                        index,
                    ),
                    "proof": {
                        "height": block.height,
                        "tx_id": tx.tx_id,
                        "index": index,
                        "merkle_root": block.merkle_root,
                        "block_hash": block.block_hash,
                        "siblings": crypto.merkle_proof(
                            [candidate.tx_id for candidate in block.transactions],
                            index,
                        ),
                    },
                }
            )

        finalized_block = next(
            candidate
            for candidate in reversed(self.store.chain)
            if candidate.status == STATUS_CONFIRMED
        )
        # The run spans the lowest transaction block through the highest
        # confirmed block; every block in between is confirmed because
        # the only pending block the chain ever carries is its tip.
        assert lowest_height is not None
        headers = [
            self._header_entry(candidate)
            for candidate in self.store.chain[
                lowest_height : finalized_block.height + 1
            ]
        ]
        finalized = self._anchor_descriptor(finalized_block)
        tip = self._fork_summary(self.store.chain)
        signer = self.store.audit_signer
        if signer is None:
            # Every snapshot (including migrated legacy ones) carries a
            # current audit signer after recovery; reaching here is a
            # programming error rather than a client-visible condition.
            raise RuntimeError(
                "no audit signer available for finalized receipts"
            )
        auth = light_client.sign_finality(
            signer["private_key"], signer["version"], finalized, tip
        )
        if auth is None:
            raise RuntimeError("current audit signer key is invalid")
        return 200, {
            "items": items,
            "headers": headers,
            "finality": {
                "finalized": finalized,
                "tip": tip,
                "auth": auth,
            },
        }

def audit_receipt_proofs(self, payload: object) -> tuple[int, dict]:
    """POST /v1/transactions/receipt-proofs/audit — offline audit summary
    for a batch of ``receipt_proof`` documents.

    The body must be a JSON object containing exactly the keys
    ``documents, expected_root`` in that order: ``documents`` a
    non-empty array whose items are each audited under the
    ``receipt_proof`` contract and ``expected_root`` the caller-pinned
    64-lowercase-hex Merkle root. A malformed body — parse failure,
    missing/extra/out-of-order keys, an empty array or an illegal root
    — is 400 with the ordered body ``{"ok": false, "error": "input"}``
    and never touches state.

    A legal batch is answered 200 with the core
    :func:`ledger.light_client.receipt_proofs_audit` result verbatim
    (key order ``ok, root, total, succeeded, errors, entries,
    digest``). The audit is a pure function of the request body: no
    state is read or written, so concurrent requests and restarts
    yield identical results.
    """
    if not isinstance(payload, dict) or tuple(payload.keys()) != (
        "documents",
        "expected_root",
    ):
        return 400, {"ok": False, "error": "input"}
    documents = payload["documents"]
    expected_root = payload["expected_root"]
    if not isinstance(documents, list) or not documents:
        return 400, {"ok": False, "error": "input"}
    if not crypto.is_hex64(expected_root):
        return 400, {"ok": False, "error": "input"}
    from . import light_client

    return 200, light_client.receipt_proofs_audit(documents, expected_root)

# -- blocks -------------------------------------------------------------

def mine_block(self) -> tuple[int, dict]:
    """Pack all pending transactions (ascending tx_id) into a pending block.

    Only allowed when the chain tip is confirmed; the new block becomes
    the pending tip until it is confirmed or rolled back.
    """
    with self.store.lock:
        if self.store.tip_is_pending():
            return 409, {"error": "tip block is pending confirmation"}
        if not self.store.pending:
            return 409, {"error": "no pending transactions"}
        ordered = sorted(self.store.pending.values(), key=lambda tx: tx.tx_id)
        block = Block.create(
            height=self.store.next_height(),
            prev_hash=self.store.tip_hash(),
            transactions=ordered,
            status=STATUS_PENDING,
        )
        self.store.chain.append(block)
        removed = [self.store.pending.pop(tx.tx_id) for tx in ordered]
        # First creation of this pending block: one block_mined event
        # carrying the block's ascending in-block transaction order.
        self.store.append_audit_event(
            EVENT_BLOCK_MINED,
            {
                "height": block.height,
                "block_hash": block.block_hash,
                "merkle_root": block.merkle_root,
                "transaction_ids": [tx.tx_id for tx in ordered],
            },
        )
        try:
            self.store.save()
        except BaseException:
            # Undo the in-memory block and its event so nothing
            # un-persisted is visible.
            self.store.chain.pop()
            self.store.pending.update({tx.tx_id: tx for tx in removed})
            self.store.truncate_audit_events(1)
            raise
    return 201, {
        "height": block.height,
        "block_hash": block.block_hash,
        "merkle_root": block.merkle_root,
        "status": block.status,
    }

def get_block(self, height: object) -> tuple[int, dict]:
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        return 200, block.to_summary()

def get_block_status(self, height: object) -> tuple[int, dict]:
    """GET /v1/blocks/{height}/status -> {height, status}; 404 if unknown."""
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        return 200, {"height": block.height, "status": block.status}

def confirm_block(self, height: object) -> tuple[int, dict]:
    """Confirm a pending tip block.

    Only a pending chain tip whose parent is confirmed can be confirmed.
    Confirming an already-confirmed block is idempotent (200); every
    other case — unknown or malformed height, non-tip pending block —
    returns 409.
    """
    height_int = _parse_height(height)
    with self.store.lock:
        if height_int is None:
            return 409, {"error": "block cannot be confirmed"}
        block = self.store.block_at(height_int)
        if block is None:
            return 409, {"error": "block cannot be confirmed"}
        if block.status == STATUS_CONFIRMED:
            # Idempotent re-confirm.
            return 200, {"height": block.height, "status": STATUS_CONFIRMED}
        if block is not self.store.tip():
            return 409, {"error": "only the chain tip can be confirmed"}
        parent = self.store.chain[-2] if len(self.store.chain) >= 2 else None
        if parent is None or parent.status != STATUS_CONFIRMED:
            return 409, {"error": "previous block is not confirmed"}
        block.status = STATUS_CONFIRMED
        # First confirmation of the pending tip: one block_confirmed
        # event; the idempotent re-confirm above appends nothing.
        self.store.append_audit_event(
            EVENT_BLOCK_CONFIRMED,
            {"height": block.height, "block_hash": block.block_hash},
        )
        try:
            self.store.save()
        except BaseException:
            block.status = STATUS_PENDING
            self.store.truncate_audit_events(1)
            raise
        return 200, {"height": block.height, "status": STATUS_CONFIRMED}

def rollback_block(self, height: object) -> tuple[int, dict]:
    """Roll back a pending tip block: delete it and restore its transactions.

    Unknown or malformed heights (including an already-rolled-back
    height) return 404; a confirmed block or a non-tip block returns 409.
    """
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        if block.status == STATUS_CONFIRMED:
            return 409, {"error": "confirmed block cannot be rolled back"}
        if block is not self.store.tip():
            return 409, {"error": "only the chain tip can be rolled back"}
        pending_before = set(self.store.pending)
        rolled_back = self.store.rollback_tip()
        # Record exactly the transactions that actually returned to the
        # mempool (rollback_tip de-duplicates ids already present), in the
        # block's ascending in-block order.
        restored_ids = [
            tx.tx_id
            for tx in rolled_back.transactions
            if tx.tx_id not in pending_before
        ]
        self.store.append_audit_event(
            EVENT_BLOCK_ROLLED_BACK,
            {
                "height": rolled_back.height,
                "block_hash": rolled_back.block_hash,
                "transaction_ids": restored_ids,
            },
        )
        try:
            self.store.save()
        except BaseException:
            # Restore the block and drop only the mempool entries we added.
            self.store.chain.append(rolled_back)
            for tx_id in list(self.store.pending):
                if tx_id not in pending_before:
                    del self.store.pending[tx_id]
            self.store.truncate_audit_events(1)
            raise
        return 200, {"height": rolled_back.height, "status": "rolled_back"}

def get_proof(self, height: object, tx_id: object) -> tuple[int, dict]:
    """Return a Merkle inclusion proof for tx_id at the given height.

    Returns 404 for an unknown height, a malformed height/tx_id, or a
    transaction absent from that block. Proofs are only issued for
    confirmed blocks; a pending block returns 409.
    """
    height_int = _parse_height(height)
    if height_int is None:
        return 404, {"error": "block not found"}
    if not crypto.is_hex64(tx_id):
        return 404, {"error": "transaction not found"}
    with self.store.lock:
        block = self.store.block_at(height_int)
        if block is None:
            return 404, {"error": "block not found"}
        if block.status != STATUS_CONFIRMED:
            return 409, {"error": "block is pending confirmation"}
        tx_ids = [tx.tx_id for tx in block.transactions]
        try:
            index = tx_ids.index(tx_id)

"""Cryptographic helpers: Ed25519 verification, SHA-256 ids and Merkle roots."""
from __future__ import annotations

import hashlib
import hmac
import json
import re

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)


def canonical_message(sender: str, recipient: str, amount: int) -> bytes:
    """Deterministic byte representation of a transaction payload.

    The payload is serialized as compact JSON with sorted keys so the same
    (from, to, amount) triple always yields identical bytes on every client.
    """
    payload = {"amount": amount, "from": sender, "to": recipient}
    return json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")


# Domain prefix of a sequenced-transfer signature message: the UTF-8 prefix
# line (including its trailing LF) followed by the compact JSON payload. It
# binds a sequenced signature to this protocol and keeps it disjoint from the
# legacy canonical-message signature domain.
SEQUENCED_MESSAGE_PREFIX = "ledger-sequenced-transfer-v1\n"


def sequenced_message(
    sender: str, recipient: str, amount: int, nonce: int
) -> bytes:
    """Deterministic byte representation of a sequenced-transfer payload.

    The message is the UTF-8 text ``ledger-sequenced-transfer-v1`` followed by
    a single LF and the compact JSON document
    ``{"amount":A,"from":F,"nonce":N,"to":T}`` with its keys sorted
    (amount, from, nonce, to) and no whitespace, so the same
    (from, to, amount, nonce) tuple always yields identical bytes.
    """
    payload = {
        "amount": amount,
        "from": sender,
        "nonce": nonce,
        "to": recipient,
    }
    body = json.dumps(
        payload, sort_keys=True, ensure_ascii=False, separators=(",", ":")
    )
    return (SEQUENCED_MESSAGE_PREFIX + body).encode("utf-8")


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def compute_tx_id(message: bytes) -> str:
    """SHA-256 hex digest of the canonical transaction message."""
    return sha256_hex(message)


def generate_private_key() -> str:
    """Generate a fresh Ed25519 private seed as 64 lowercase hex chars."""
    return Ed25519PrivateKey.generate().private_bytes(
        serialization.Encoding.Raw,
        serialization.PrivateFormat.Raw,
        serialization.NoEncryption(),
    ).hex()


def derive_public_key(private_key_hex: str) -> str | None:
    """Derive the 64-hex Ed25519 public key from a 64-hex private seed.

    Returns None for malformed hex or a wrong-length seed rather than raising,
    so callers can treat every malformed key uniformly as a 400.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return _public_hex(private_key)


def _public_hex(private_key: Ed25519PrivateKey) -> str:
    return private_key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


def sign_message(private_key_hex: str, message: bytes) -> str | None:
    """Sign ``message`` with an Ed25519 seed (64 hex chars); hex signature.

    Returns None for a malformed private key rather than raising.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return private_key.sign(message).hex()


def verify_signature(public_key_hex: str, message: bytes, signature_hex: str) -> bool:
    """Verify an Ed25519 signature (public key and signature are hex strings).

    Returns False for malformed hex or wrong key/signature lengths rather than
    raising, so callers can treat every verification failure uniformly.
    """
    try:
        public_bytes = bytes.fromhex(public_key_hex)
        signature_bytes = bytes.fromhex(signature_hex)
    except ValueError:
        return False
    if len(public_bytes) != 32 or len(signature_bytes) != 64:
        return False
    try:
        public_key = Ed25519PublicKey.from_public_bytes(public_bytes)
        public_key.verify(signature_bytes, message)
    except (InvalidSignature, ValueError):
        return False
    return True


# Merkle root of an empty transaction list; fixed so genesis blocks are identical.
EMPTY_MERKLE_ROOT = sha256_hex(b"")


def merkle_root(tx_ids: list[str]) -> str:
    """SHA-256 Merkle root of the given tx ids.

    Levels are built by hashing ``sha256(left + right)`` hex-string pairs;
    a lone odd node at a level is promoted by pairing it with itself.
    Callers normally pass ids already sorted ascending.
    """
    if not tx_ids:
        return EMPTY_MERKLE_ROOT
    level = list(tx_ids)
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
    return level[0]


# A SHA-256 digest rendered as 64 lowercase hexadecimal characters.
_HEX64_RE = re.compile(r"[0-9a-f]{64}")

# A 64-byte Ed25519 signature rendered as 128 lowercase hex characters.
_HEX128_RE = re.compile(r"[0-9a-f]{128}")

# Maximum Merkle depth we accept: 64 sibling levels already cover trees with up
# to 2**64 leaves, so a longer sibling path is necessarily malformed.
MAX_MERKLE_DEPTH = 64


def _is_hex64(value: object) -> bool:
    return isinstance(value, str) and _HEX64_RE.fullmatch(value) is not None


def is_hex64(value: object) -> bool:
    """True iff ``value`` is a 64-char lowercase SHA-256 hex string."""
    return _is_hex64(value)


def is_hex128(value: object) -> bool:
    """True iff ``value`` is a 128-char lowercase Ed25519 signature hex string."""
    return isinstance(value, str) and _HEX128_RE.fullmatch(value) is not None


def merkle_proof(tx_ids: list[str], index: int) -> list[dict]:
    """Sibling path from the leaf at ``index`` up to the Merkle root.

    Mirrors :func:`merkle_root`: levels hash ``sha256(left + right)`` hex pairs
    and a lone odd node is paired with itself. Each returned item has a
    ``direction`` ("left" or "right") recording which side the *sibling* sits
    on relative to the path node, and the sibling's ``hash``. Items are ordered
    from the leaf level toward the root. Raises ValueError for an empty list or
    an out-of-range index.
    """
    if not tx_ids:
        raise ValueError("cannot build a Merkle proof for an empty tree")
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("index must be an integer")
    if index < 0 or index >= len(tx_ids):
        raise ValueError("transaction index out of range")

    level = list(tx_ids)
    position = index
    siblings: list[dict] = []
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        if position % 2 == 0:
            # Path node is the left child; sibling sits on its right.
            siblings.append({"direction": "right", "hash": level[position + 1]})
        else:
            # Path node is the right child; sibling sits on its left.
            siblings.append({"direction": "left", "hash": level[position - 1]})
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
        position //= 2
    return siblings


def verify_merkle_proof(
    tx_id: str,
    siblings: list[dict],
    merkle_root: str,
    block_hash: str,
    expected_block_hash: str,
) -> bool:
    """Verify a Merkle proof and bind it to a specific block hash.

    Re-hashes the leaf (``tx_id``) with the sibling path from leaf to root and
    compares the result with ``merkle_root``; ``block_hash`` must additionally
    equal ``expected_block_hash``. Every malformed input (non-64-char lowercase
    hex hash, illegal direction, non-list path, excessive depth) and every
    mismatch returns False rather than raising.
    """
    try:
        if not _is_hex64(tx_id):
            return False
        if not _is_hex64(merkle_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_block_hash):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        current = tx_id
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            if direction == "left":
                pair = sibling_hash + current
            elif direction == "right":
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))

        if not hmac.compare_digest(current, merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# Exact, ordered key sets of a batch Merkle-proof response document. They let
# verify_merkle_proof_bundle reject missing/extra keys *and* a wrong key order.
_BUNDLE_TOP_KEYS = ("height", "block_hash", "merkle_root", "transaction_ids", "proofs")
_BUNDLE_PROOF_KEYS = ("tx_id", "index", "siblings")
_BUNDLE_SIBLING_KEYS = ("direction", "hash")


def _exact_keys(value: object, keys: tuple[str, ...]) -> bool:
    """True iff ``value`` is a dict with exactly ``keys``, in that insertion order."""
    return isinstance(value, dict) and tuple(value.keys()) == keys


def verify_merkle_proof_bundle(
    bundle: object,
    expected_block_hash: object,
    expected_merkle_root: object,
) -> bool:
    """Strictly verify a batch Merkle-proof bundle offline.

    The bundle mirrors POST /v1/blocks/{height}/proofs::

        {"height": H, "block_hash": B, "merkle_root": R,
         "transaction_ids": [id, ...],     # ALL block leaves, ascending
         "proofs": [{"tx_id", "index", "siblings"}, ...]}  # requested subset

    ``transaction_ids`` is the block's complete, ascending leaf list; ``proofs``
    covers the requested tx_ids (a subset of it), itself sorted by tx_id. Every
    proof's leaf-to-root sibling path is re-hashed with the same pairing rules
    as :func:`merkle_root` (``sha256(left + right)`` hex pairs, a lone odd node
    paired with itself); the root is additionally recomputed directly from
    ``transaction_ids`` and must equal both the bundle's ``merkle_root`` and
    ``expected_merkle_root``, while ``block_hash`` must equal
    ``expected_block_hash``. Each proof ``index`` must be the tx_id's exact
    position in ``transaction_ids`` and its path must agree with that index at
    every level.

    Every defect — a missing/extra key, a wrong key order, a wrong type, a
    non-boolean/negative height, a duplicate/non-hex/non-string/unsorted tx_id,
    an unknown or duplicated proof tx_id, an out-of-range index, a path
    inconsistent with the index (including the phantom self-pair slot), an
    illegal direction or hash, excessive depth, an empty proof list, a tampered
    leaf list/root or block hash — returns False rather than raising.
    """
    try:
        if not _exact_keys(bundle, _BUNDLE_TOP_KEYS):
            return False
        if not _is_hex64(expected_block_hash) or not _is_hex64(expected_merkle_root):
            return False
        height = bundle["height"]
        block_hash = bundle["block_hash"]
        bundle_root = bundle["merkle_root"]
        transaction_ids = bundle["transaction_ids"]
        proofs = bundle["proofs"]

        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            return False
        if not _is_hex64(block_hash):
            return False
        if not _is_hex64(bundle_root):
            return False
        if not isinstance(transaction_ids, list) or not transaction_ids:
            return False
        if not isinstance(proofs, list) or not proofs:
            return False
        if any(not _is_hex64(tx_id) for tx_id in transaction_ids):
            return False
        # Unique leaves ...
        if len(set(transaction_ids)) != len(transaction_ids):
            return False
        # ... in ascending tx_id order, matching the block's leaf ordering.
        if transaction_ids != sorted(transaction_ids):
            return False
        # The root is recomputed straight from the claimed leaf list, so the
        # list can never be tampered with independently of the paths.
        if not hmac.compare_digest(merkle_root(transaction_ids), bundle_root):
            return False

        positions = {tx_id: i for i, tx_id in enumerate(transaction_ids)}
        proof_ids: list[str] = []
        leaf_count = len(transaction_ids)
        for proof in proofs:
            if not _exact_keys(proof, _BUNDLE_PROOF_KEYS):
                return False
            tx_id = proof["tx_id"]
            index = proof["index"]
            siblings = proof["siblings"]
            if not _is_hex64(tx_id) or tx_id not in positions:
                return False
            if tx_id in proof_ids:
                return False
            if isinstance(index, bool) or not isinstance(index, int):
                return False
            # The index must be exactly the tx_id's leaf position; anything
            # else is a mismatch or out of range regardless of supplied hashes.
            if index != positions[tx_id] or not 0 <= index < leaf_count:
                return False
            if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
                return False

            # A depth-D path addresses one of 2**D leaf slots.
            depth = len(siblings)
            if index >= (1 << depth):
                return False
            current = tx_id
            position = index
            for item in siblings:
                if not _exact_keys(item, _BUNDLE_SIBLING_KEYS):
                    return False
                direction = item["direction"]
                sibling_hash = item["hash"]
                if not _is_hex64(sibling_hash):
                    return False
                # The odd-node promotion pairs the last (even-positioned) node
                # with a copy of itself, so a genuine self-pair always points
                # at a right sibling. A left sibling equal to the current node
                # addresses the phantom duplicate slot, which is never a real
                # leaf. The path must also agree with the index at every
                # level: an even position is the left child (sibling on its
                # right), an odd position the right child.
                if direction == "left":
                    if position % 2 == 0 or sibling_hash == current:
                        return False
                    pair = sibling_hash + current
                elif direction == "right":
                    if position % 2 == 1:
                        return False
                    pair = current + sibling_hash
                else:
                    return False
                current = sha256_hex(pair.encode("ascii"))
                position //= 2

            if not hmac.compare_digest(current, bundle_root):
                return False
            proof_ids.append(tx_id)

        # Proofs must be unique and ordered by tx_id ascending.
        if proof_ids != sorted(proof_ids):
            return False

        if not hmac.compare_digest(bundle_root, expected_merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# -- account state Merkle tree ----------------------------------------------


def account_state_leaf(
    account: str, balance: int, confirmed_transactions: list[str]
) -> str:
    """SHA-256 leaf of one account's confirmed state.

    The leaf is ``sha256(utf8(JSON))`` of the canonical compact JSON document
    ``{"account":a,"balance":b,"confirmed_transactions":T}`` serialized with
    ``sort_keys=True``, ``ensure_ascii=False`` and ``separators=(",",":")``.
    ``T`` keeps its original (on-chain) order; ``sort_keys`` only orders the
    three top-level keys.
    """
    document = {
        "account": account,
        "balance": balance,
        "confirmed_transactions": confirmed_transactions,
    }
    raw = json.dumps(
        document, sort_keys=True, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    return sha256_hex(raw)


def account_state_root(leaves: list[str]) -> str:
    """Merkle root of account-state leaves ordered by ascending account.

    Uses the same pairing rules as :func:`merkle_root` (hex-string pairs
    hashed ``sha256(left + right)``, a lone odd node paired with itself); an
    empty account set has the same root as an empty tx list.
    """
    return merkle_root(leaves)


def verify_account_proof(
    proof: object,
    expected_root: object,
    expected_height: object,
    expected_hash: object,
) -> bool:
    """Verify an account-state Merkle proof offline.

    Recomputes the account leaf from
    ``{account, balance, confirmed_transactions}``, walks the leaf-to-root
    ``siblings`` path, and requires the recomputed root to equal both the
    proof's ``state_root`` and ``expected_root``, while ``height`` /
    ``block_hash`` anchor the tree to the expected confirmed tip. Every
    malformed input — a non-64-char lowercase hex hash or anchor, an illegal
    direction, an illegal index, a malformed leaf/balance/transaction list, a
    path inconsistent with the index, excessive depth — returns False rather
    than raising.
    """
    try:
        if not isinstance(proof, dict):
            return False
        account = proof.get("account")
        balance = proof.get("balance")
        transactions = proof.get("confirmed_transactions")
        index = proof.get("index")
        state_root = proof.get("state_root")
        height = proof.get("height")
        block_hash = proof.get("block_hash")
        siblings = proof.get("siblings")

        if not isinstance(account, str) or not account:
            return False
        if isinstance(balance, bool) or not isinstance(balance, int) or balance < 0:
            return False
        if not isinstance(transactions, list):
            return False
        if any(not _is_hex64(tx_id) for tx_id in transactions):
            return False
        if isinstance(index, bool) or not isinstance(index, int) or index < 0:
            return False
        if not isinstance(height, bool) and isinstance(height, int):
            if height < 0:
                return False
        else:
            return False
        if not _is_hex64(state_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_hash):
            return False
        if not _is_hex64(expected_root):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        # The leaf is always recomputed from the proof's own triple; a
        # client-supplied leaf value is never trusted.
        depth = len(siblings)
        # A depth-D path addresses one of 2**D leaf slots; a single-leaf tree
        # (D == 0) can only ever be index 0. An index outside that range is
        # illegal regardless of any hashes the caller supplies.
        if index >= (1 << depth):
            return False
        current = account_state_leaf(account, balance, transactions)
        position = index
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            # The odd-node promotion pairs the last (even-positioned) node
            # with a copy of itself, so a genuine self-pair always points at a
            # right sibling. A left sibling equal to the current node addresses
            # the phantom duplicate slot, which is never a real account.
            if direction == "left" and sibling_hash == current:
                return False
            # The path must agree with the index: at every level an even
            # position is the left child (sibling on its right) and an odd
            # position the right child.
            if direction == "left":
                if position % 2 == 0:
                    return False
                pair = sibling_hash + current
            elif direction == "right":
                if position % 2 == 1:
                    return False
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))
            position //= 2

        if not hmac.compare_digest(current, state_root):
            return False
        if not hmac.compare_digest(current, expected_root):
            return False
        if height != expected_height:
            return False
        if not hmac.compare_digest(block_hash, expected_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# Exact key shapes of the account-absence proof document and its parts.
_ABSENCE_DOC_KEYS = ("account", "state", "lower", "upper")
_ABSENCE_STATE_KEYS = (
    "state_root",
    "height",
    "block_hash",
    "account_count",
)
_ABSENCE_NEIGHBOR_KEYS = (
    "account",
    "balance",
    "confirmed_transactions",
    "index",
    "state_root",
    "height",
    "block_hash",
    "siblings",
)


def verify_account_absence_proof(
    document: object, account: object, expected_state: object
) -> bool:
    """Verify an account-absence (non-membership) proof offline.

    The document mirrors
    ``GET /v1/accounts/{account}/absence-proof``::

        {"account": A, "state": state-anchor-document,
         "lower": neighbor-inclusion-proof | None,
         "upper": neighbor-inclusion-proof | None}

    ``account`` is the caller-pinned target (a non-empty string) and
    ``expected_state`` is the caller-pinned full state-root document
    (``state_root, height, block_hash, account_count``). The proof is valid
    only when:

    * every document/state/neighbor field is present exactly once with the
      right type and format (booleans are never integers; neighbor sibling
      items carry exactly ``direction``/``hash``);
    * the document account equals the pinned account and the embedded state
      anchor exactly equals ``expected_state`` (root, height, block hash and
      account count);
    * each non-null neighbor is a valid inclusion proof against the same
      anchor, with its index in ``[0, account_count)``;
    * the neighbors genuinely frame the target in ascending account order:
      a present ``lower`` sits one slot below it (``lower.account < account``,
      index ``i``), a present ``upper`` one slot above
      (``account < upper.account``, index ``i + 1``), with both present
      adjacent (``i, i + 1``); a boundary proof uses only index 0 (target
      before the first account) or ``account_count - 1`` (target after the
      last); an empty tree has ``account_count == 0`` and both sides null;
    * the empty-tree root is the fixed empty Merkle root.

    Returns False — never raises — for any malformed or tampered input,
    including mixed anchors, non-adjacent neighbors, out-of-range indices and
    phantom slots derived from odd-node self-pairing. Key order is
    irrelevant (but missing/extra keys still fail).
    """
    try:
        if not isinstance(document, dict):
            return False
        # Key order is irrelevant for the absence document, but the four
        # keys must be present with none missing or extra.
        if set(document.keys()) != set(_ABSENCE_DOC_KEYS):
            return False
        target = document["account"]
        state = document["state"]
        lower = document["lower"]
        upper = document["upper"]

        if not isinstance(account, str) or not account:
            return False
        if not isinstance(target, str) or not target or target != account:
            return False

        state = _validated_absence_state(state, expected_state)
        if state is None:
            return False
        root = state["state_root"]
        height = state["height"]
        block_hash = state["block_hash"]
        account_count = state["account_count"]

        if account_count == 0:
            if root != EMPTY_MERKLE_ROOT:
                return False
            return lower is None and upper is None

        lower_result = None
        upper_result = None
        if lower is not None:
            lower_result = _validated_absence_neighbor(
                lower, root, height, block_hash, account_count
            )
            if lower_result is None:
                return False
            name, _index = lower_result
            if not name < account:
                return False
        if upper is not None:
            upper_result = _validated_absence_neighbor(
                upper, root, height, block_hash, account_count
            )
            if upper_result is None:
                return False
            name, _index = upper_result
            if not account < name:
                return False

        if lower_result is not None and upper_result is not None:
            if lower_result[1] + 1 != upper_result[1]:
                return False
        elif lower_result is not None:
            # Target past the last account: the only neighbor is the last row.
            if lower_result[1] != account_count - 1:
                return False
        elif upper_result is not None:
            # Target before the first account: the only neighbor is row zero.
            if upper_result[1] != 0:
                return False
        else:
            # A non-empty tree must name at least one framing neighbor.
            return False
        return True
    except (TypeError, ValueError):
        return False


def _validated_absence_state(state: object, expected_state: object) -> dict | None:
    """Validate and return the embedded state anchor iff it exactly matches
    the caller-pinned ``expected_state`` document (same four keys/types)."""
    if not isinstance(state, dict):
        return None
    if set(state.keys()) != set(_ABSENCE_STATE_KEYS):
        return None
    if not isinstance(expected_state, dict):
        return None
    if set(expected_state.keys()) != set(_ABSENCE_STATE_KEYS):
        return None
    expected_root = expected_state["state_root"]
    expected_height = expected_state["height"]
    expected_hash = expected_state["block_hash"]
    expected_count = expected_state["account_count"]
    if not _is_hex64(expected_root) or not _is_hex64(expected_hash):
        return None
    if (
        isinstance(expected_height, bool)
        or not isinstance(expected_height, int)
        or expected_height < 0
    ):
        return None
    if (
        isinstance(expected_count, bool)
        or not isinstance(expected_count, int)
        or expected_count < 0
    ):
        return None
    root = state["state_root"]
    height = state["height"]
    block_hash = state["block_hash"]
    account_count = state["account_count"]
    if not _is_hex64(root) or not _is_hex64(block_hash):
        return None
    if isinstance(height, bool) or not isinstance(height, int) or height < 0:
        return None
    if (
        isinstance(account_count, bool)
        or not isinstance(account_count, int)
        or account_count < 0
    ):
        return None
    if root != expected_root:
        return None
    if height != expected_height:
        return None
    if block_hash != expected_hash:
        return None
    if account_count != expected_count:
        return None
    return {
        "state_root": root,
        "height": height,
        "block_hash": block_hash,
        "account_count": account_count,
    }


def _validated_absence_neighbor(
    neighbor: object,
    root: str,
    height: int,
    block_hash: str,
    account_count: int,
) -> tuple[str, int] | None:
    """Validate one framing neighbor inclusion proof against the shared
    anchor; return ``(account, index)`` on success."""
    if not isinstance(neighbor, dict):
        return None
    if set(neighbor.keys()) != set(_ABSENCE_NEIGHBOR_KEYS):
        return None
    siblings = neighbor["siblings"]
    if not isinstance(siblings, list):
        return None
    for item in siblings:
        if not isinstance(item, dict) or set(item.keys()) != {"direction", "hash"}:
            return None
    name = neighbor["account"]
    index = neighbor["index"]
    if not isinstance(name, str) or not name:
        return None
    if isinstance(index, bool) or not isinstance(index, int):
        return None
    if index < 0 or index >= account_count:
        return None
    if not verify_account_proof(neighbor, root, height, block_hash):
        return None
    return name, index

            for key in HISTORY_CREDENTIAL_KEYS
        }
    # Uniform Idempotency-Key records are part of the same atomic document
    # as the ledger/admin change they deduplicated. The frozen request
    # canonical text and the exact on-wire response JSON text are stored as
    # strings so key order and byte shape survive a snapshot round-trip.
    if self.idempotency:
        data[IDEMPOTENCY_SECTION] = [
            {
                "key": key,
                "method": rec["method"],
                "target": rec["target"],
                "request": rec["request"],
                "fingerprint": rec["fingerprint"],
                "status": rec["status"],
                "body": rec["body"],
            }
            for key, rec in sorted(self.idempotency.items())
        ]
    # Per-account sequenced-transfer reservations are persisted in the
    # same atomic document as the chain/pending they are derived from.
    # The section is written only while at least one sender has a
    # sequenced transfer, so a ledger that never uses the feature keeps
    # the legacy snapshot layout; a snapshot missing the section
    # recovers the same empty view.
    if next_sequences:
        data["sequences"] = [
            {
                "account": account,
                "confirmed": [
                    {"nonce": nonce, "tx_id": next_sequences[account]["confirmed"][nonce]}
                    for nonce in sorted(next_sequences[account]["confirmed"])
                ],
                "pending": [
                    {"nonce": nonce, "tx_id": next_sequences[account]["pending"][nonce]}
                    for nonce in sorted(next_sequences[account]["pending"])
                ],
            }
            for account in sorted(next_sequences)
        ]
    directory = os.path.dirname(os.path.abspath(self.path)) or "."
    os.makedirs(directory, exist_ok=True)
    # Hold the class-wide recovery lock while a .ledger-* snapshot exists
    # on disk, so a concurrent in-process LedgerStore construction cannot
    # scan a half-written promotion.
    with self._recovery_lock:
        fd, tmp_path = tempfile.mkstemp(
            prefix=SNAPSHOT_PREFIX,
            suffix=f".gen{next_generation}",
            dir=directory,
        )
        promoted = False
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as fh:
                # Snapshot wire format: ascending keys, the default
                # separators, non-ASCII kept literal, UTF-8 encoding and a
                # single terminating LF.
                json.dump(data, fh, ensure_ascii=False, sort_keys=True)
                fh.write("\n")
                fh.flush()
                os.fsync(fh.fileno())
            os.replace(tmp_path, self.path)
            promoted = True
            self._fsync_dir(directory)
            # Promotion is durable: now publish the prospective derived
            # views and advance the generation, together and last, so a
            # successful write is the only thing that changes memory.
            self.tx_index = next_index
            self.accounts = next_accounts
            self.sequences = next_sequences
            self.generation = next_generation
        finally:
            if not promoted and os.path.exists(tmp_path):
                # Promotion never happened: drop the half-written candidate so
                # it cannot masquerade as a recoverable snapshot. A candidate
                # written and fsynced *before* a crash during replace survives
                # precisely because that crash skips this cleanup.
                try:
                    os.unlink(tmp_path)
                except OSError:
                    pass

@staticmethod
def _fsync_dir(directory: str) -> None:
    """Best-effort directory fsync so a rename survives a power loss."""
    try:
        dir_fd = os.open(directory, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    except OSError:
        return
    try:
        os.fsync(dir_fd)
    except OSError:
        pass
    finally:
        os.close(dir_fd)

# -- chain helpers --------------------------------------------------------

def tip(self) -> Block:
    return self.chain[-1]

def tip_hash(self) -> str:
    return self.chain[-1].block_hash

def next_height(self) -> int:
    return self.chain[-1].height + 1

def tip_is_pending(self) -> bool:
    return self.chain[-1].status == STATUS_PENDING

def block_at(self, height: int) -> Block | None:
    if 0 <= height < len(self.chain) and self.chain[height].height == height:
        return self.chain[height]
    return None

def rollback_tip(self) -> Block:
    """Remove the pending tip block and return its transactions to the mempool.

    Transactions are restored de-duplicated: an id already present in the
    pending set (resubmitted while the block was unconfirmed) is kept as
    is, not overwritten. Caller must hold the lock and must have checked
    that the tip is a pending block. Does not save; callers persist.
    """
    block = self.chain.pop()
    for tx in block.transactions:
        self.pending.setdefault(tx.tx_id, tx)
    return block

# -- fork candidates ------------------------------------------------------

@staticmethod
def _valid_tx_fields(tx: Transaction) -> None:
    """Structural checks shared by candidate submission and recovery."""
    if not isinstance(tx.sender, str) or not tx.sender:
        raise ValueError("transaction has an invalid 'from' field")
    if not isinstance(tx.recipient, str) or not tx.recipient:
        raise ValueError("transaction has an invalid 'to' field")
    if isinstance(tx.amount, bool) or not isinstance(tx.amount, int) or tx.amount <= 0:
        raise ValueError("transaction amount must be a positive integer")
    if not isinstance(tx.signature, str) or not tx.signature:
        raise ValueError("transaction is missing a signature")

@staticmethod
def replay_sequenced_nonces(blocks: list[Block]) -> None:
    """Enforce the per-sender nonce stream across an ordered block list.

    Transactions are stored ascending by tx_id inside each block, so one
    sender's sequenced nonces may appear in any within-block order; across
    block heights, however, each block's per-sender nonce set must be
    exactly the next dense run ``{expected, ..., expected+k-1}``. A gap, a
    duplicated nonce, a non-zero first nonce or an inversion across
    heights raises ValueError. Legacy (nonce-less) transfers are outside
    the stream.
    """
    next_nonces: dict[str, int] = {}
    for block in blocks:
        block_nonces: dict[str, list[int]] = {}
        for tx in block.transactions:
            if tx.nonce is not None:
                block_nonces.setdefault(tx.sender, []).append(tx.nonce)
        for sender, nonces in block_nonces.items():
            expected_nonce = next_nonces.get(sender, 0)
            ordered = sorted(nonces)
            if len(set(nonces)) != len(nonces):
                raise ValueError(
                    f"sender {sender} uses a duplicated sequenced nonce in "
                    f"block {block.height}"
                )
            if ordered != list(
                range(expected_nonce, expected_nonce + len(ordered))
            ):
                raise ValueError(
                    f"sequenced nonces {ordered} for sender {sender} in block "
                    f"{block.height} do not continue the stream at "
                    f"nonce {expected_nonce}"
                )
            next_nonces[sender] = expected_nonce + len(ordered)

def _parse_verified_chain(
    self, blocks_raw: object, endowment: int, genesis: Block | None = None
) -> list[Block]:
    """Strictly validate a block list submitted as (or persisted as) a fork.

    The list must start from the canonical genesis block, connect through
    consecutive heights and prev_hash values, and carry recomputed-correct
    Merkle roots and block hashes. Transactions must have valid Ed25519
    signatures, ascending and globally unique tx_ids, and a replay from the
    per-identity endowment must never overspend. All blocks must be
    confirmed except an optional pending tip. Raises ValueError on any
    defect.
    """
    if not isinstance(blocks_raw, list) or not blocks_raw:
        raise ValueError("'blocks' must be a non-empty list")
    genesis = genesis if genesis is not None else self.chain[0]
    blocks: list[Block] = []
    seen_tx_ids: set[str] = set()
    for i, block_raw in enumerate(blocks_raw):
        if not isinstance(block_raw, dict):
            raise ValueError(f"block at position {i} is not a JSON object")
        try:
            block = Block.from_dict(block_raw)
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError(f"block {i} is malformed: {exc}") from exc
        if isinstance(block.height, bool) or block.height != i:
            raise ValueError(
                f"block at position {i} has non-consecutive height {block.height}"
            )
        expected_prev = GENESIS_PREV_HASH if i == 0 else blocks[i - 1].block_hash
        if block.prev_hash != expected_prev:
            raise ValueError(f"block {i} has a mismatched prev_hash")
        if block.status not in (STATUS_PENDING, STATUS_CONFIRMED):
            raise ValueError(f"block {i} has unknown status {block.status!r}")
        if i == 0:
            # The candidate must connect to *the* canonical genesis.
            if (
                block.status != STATUS_CONFIRMED
                or block.transactions
                or block.block_hash != genesis.block_hash
                or block.merkle_root != genesis.merkle_root
            ):
                raise ValueError("first block must be the canonical genesis block")
        elif i < len(blocks_raw) - 1 and block.status == STATUS_PENDING:
            raise ValueError(f"pending block {i} is not the chain tip")

        txs_raw = block_raw.get("transactions")
        if not isinstance(txs_raw, list):
            raise ValueError(f"block {i} transactions must be a list")
        tx_ids: list[str] = []
        for j, tx in enumerate(block.transactions):
            self._valid_tx_fields(tx)
            if not crypto.verify_signature(tx.sender, tx.message, tx.signature):
                raise ValueError(f"block {i} transaction {j} has an invalid signature")
            stored_id = txs_raw[j].get("tx_id") if isinstance(txs_raw[j], dict) else None
            if stored_id != tx.tx_id:
                raise ValueError(
                    f"block {i} transaction {j} has a mismatched tx_id"
                )
            if tx.tx_id in seen_tx_ids:
                raise ValueError(f"duplicate transaction {tx.tx_id} in candidate")
            seen_tx_ids.add(tx.tx_id)
            tx_ids.append(tx.tx_id)
        if tx_ids != sorted(tx_ids):
            raise ValueError(f"block {i} transactions are not tx_id sorted")
        if crypto.merkle_root(tx_ids) != block.merkle_root:
            raise ValueError(f"block {i} Merkle root mismatch")
        if (
            compute_block_hash(block.height, block.prev_hash, block.merkle_root)
            != block.block_hash
        ):
            raise ValueError(f"block {i} block_hash mismatch")
        blocks.append(block)

    # Replay every transaction from the per-identity endowment; unconfirmed
    # (pending tip) transactions are included so a candidate can never hide
    # an overspend behind a pending final block.
    balances: dict[str, int] = {}
    for block in blocks:
        for tx in block.transactions:
            sender_balance = balances.get(tx.sender, endowment)
            if sender_balance < tx.amount:
                raise ValueError(
                    f"replay overspend by {tx.sender} in block {block.height}"
                )
            balances[tx.sender] = sender_balance - tx.amount
            balances[tx.recipient] = balances.get(tx.recipient, endowment) + tx.amount
    # The same replay enforces the per-sender sequenced-transfer nonce
    # stream from genesis (dense across heights, within-block order
    # irrelevant because transactions are stored ascending by tx_id).
    self.replay_sequenced_nonces(blocks)
    return blocks

def validate_fork_blocks(self, blocks_raw: object) -> list[Block]:
    """Validate and parse a candidate fork submitted by a client.

    The blocks must start from the canonical genesis block, connect via
    consecutive heights and prev_hash, carry correct block hashes and
    Merkle roots, unique ascending tx_ids with valid Ed25519 signatures and
    no replay overspend, and be all confirmed except an optional pending
    tip. Raises ValueError with a descriptive reason on any defect.
    """
    endowment = (
        self.initial_balance if self.initial_balance is not None else 1_000_000
    )
    return self._parse_verified_chain(blocks_raw, endowment)

@staticmethod
def validate_range_tail(anchor: dict, blocks_raw: object) -> list[Block]:
    """Strictly verify an incremental range's delivered tail standalone.

    Used both when a range delivery is first received and when range sync
    records are re-verified on restart; it never splices in (or depends on)
    the current canonical chain, so a same-key retry stays verifiable after
    the receiver's canonical chain has advanced. The tail must be a
    non-empty list of well-formed blocks whose heights start at
    ``anchor.height + 1`` and stay consecutive, whose first ``prev_hash``
    is the anchor hash (later ones linking internally), with
    recomputed-correct Merkle roots and block hashes, valid Ed25519
    signatures, tx_ids unique within the tail and ascending inside each
    block, and pending status only on its final block. Endowment replay is
    not part of this standalone check (it needs the canonical-prefix
    balances and is run on the assembled chain at first reception).
    Raises ValueError on any defect and returns the parsed tail Blocks.
    """
    if not isinstance(blocks_raw, list) or not blocks_raw:
        raise ValueError("'blocks' must be a non-empty list")
    tail: list[Block] = []
    seen_tx_ids: set[str] = set()
    expected_prev = anchor["block_hash"]
    for i, block_raw in enumerate(blocks_raw):
        if not isinstance(block_raw, dict):
            raise ValueError(f"block at position {i} is not a JSON object")
        try:
            block = Block.from_dict(block_raw)
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError(f"block {i} is malformed: {exc}") from exc
        expected_height = anchor["height"] + 1 + i
        if isinstance(block.height, bool) or block.height != expected_height:
            raise ValueError(
                f"block at position {i} has height {block.height}, "
                f"expected {expected_height}"
            )
        if block.prev_hash != expected_prev:
            raise ValueError(f"block {i} has a mismatched prev_hash")
        if block.status not in (STATUS_PENDING, STATUS_CONFIRMED):
            raise ValueError(f"block {i} has unknown status {block.status!r}")
        if i < len(blocks_raw) - 1 and block.status == STATUS_PENDING:
            raise ValueError(f"pending block {i} is not the chain tip")
        txs_raw = block_raw.get("transactions")
        if not isinstance(txs_raw, list):
            raise ValueError(f"block {i} transactions must be a list")

def _parse_persisted_sequences(raw: object, path: str) -> dict[str, dict] | None:
    """Strictly parse the optional per-account ``sequences`` section.

    Returns None when the section is absent (a pre-sequence snapshot); an
    empty list parses to an empty table. Each entry carries exactly
    ``account`` plus two lists of ``{nonce, tx_id}`` pairs,
    ``confirmed`` then ``pending``. The pairs are stored ascending by
    nonce with distinct nonces; the two lists together must satisfy the
    same partition invariant as the live derived view (confirmed nonces a
    dense 0..c-1 prefix, pending nonces continuing c..c+p-1 with no
    overlap). Any defect is snapshot corruption.
    """
    if raw is None:
        return None
    if not isinstance(raw, list):
        raise StateRecoveryError(path, "'sequences' must be a list")
    result: dict[str, dict] = {}

    def parse_pairs(value: object, where: str) -> dict[int, str]:
        if not isinstance(value, list):
            raise StateRecoveryError(path, f"{where} must be a list")
        pairs: dict[int, str] = {}
        previous = -1
        for j, item in enumerate(value):
            if not isinstance(item, dict) or set(item) != {"nonce", "tx_id"}:
                raise StateRecoveryError(
                    path,
                    f"{where} entry {j} must be an object with exactly "
                    "nonce and tx_id",
                )
            nonce = item["nonce"]
            tx_id = item["tx_id"]
            if isinstance(nonce, bool) or not isinstance(nonce, int) or nonce < 0:
                raise StateRecoveryError(
                    path, f"{where} entry {j} nonce must be a non-negative integer"
                )
            if not crypto.is_hex64(tx_id):
                raise StateRecoveryError(
                    path,
                    f"{where} entry {j} tx_id must be 64 lowercase hex characters",
                )
            if nonce <= previous:
                raise StateRecoveryError(
                    path, f"{where} nonces must be strictly ascending"
                )
            if nonce in pairs:
                raise StateRecoveryError(path, f"{where} has a duplicated nonce")
            pairs[nonce] = tx_id
            previous = nonce
        return pairs

    for index, entry in enumerate(raw):
        where = f"sequences entry {index}"
        if not isinstance(entry, dict) or set(entry) != {
            "account",
            "confirmed",
            "pending",
        }:
            raise StateRecoveryError(
                path,
                f"{where} must contain exactly account, confirmed and pending",
            )
        account = entry["account"]
        if not isinstance(account, str) or not account:
            raise StateRecoveryError(
                path, f"{where} account must be a non-empty string"
            )
        if account in result:
            raise StateRecoveryError(
                path, f"duplicate sequences entry for account {account}"
            )
        confirmed = parse_pairs(entry["confirmed"], f"{where} confirmed")
        pending_pairs = parse_pairs(entry["pending"], f"{where} pending")
        result[account] = {"confirmed": confirmed, "pending": pending_pairs}
    LedgerStore.validate_sequence_partitions(result, path)
    return result

